update core_material
title = #{title}, author = #{author}, summary = #{summary}, content = #{content}, original_url = #{originalUrl}, original_id = #{originalId}, reply_count = #{replyCount}, like_count = #{likeCount}, view_count = #{viewCount}, share_count = #{shareCount}, comment_count = #{commentCount}, publish_time = #{publishTime}, content_type = #{contentType}, package_type = #{packageType}, status = #{status}, is_top = #{isTop}, source = #{source}, cover_image = #{coverImage}, video_url = #{videoUrl}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
